import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Context 组：模型这一轮看到什么","description":"提示之上的下一问：内容。五个主题回答模型单轮可见内容的全部工程问题——窗口硬预算、组装策略、跨轮会话、仓库约定；入口是 prompt，出口是算得清预算、组得对来源、防得住腐烂。","frontmatter":{"title":"Context 组：模型这一轮看到什么","description":"提示之上的下一问：内容。五个主题回答模型单轮可见内容的全部工程问题——窗口硬预算、组装策略、跨轮会话、仓库约定；入口是 prompt，出口是算得清预算、组得对来源、防得住腐烂。","domain":"tech","tags":["context","index","navigation"],"navOrder":30,"topicId":"context-index","layer":"3","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":["structured-output"],"next":["prompt","context-window","context","session-state","repo-context"],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/03-context/index.md","filePath":"zh/tech/03-context/index.md","lastUpdated":1788326832000}'),o={name:"zh/tech/03-context/index.md"};function d(i,t,s,l,h,c){return r(),n("div",null,[...t[0]||(t[0]=[a(`<blockquote><p><strong>所在组</strong>：Context 组（本组导览） ｜ <strong>上一组出口</strong>：接口契约与推理形态 ｜ <strong>本组出口</strong>：能按预算组装单轮上下文并管理跨轮记忆</p></blockquote><h1 id="context-组-模型这一轮看到什么" tabindex="-1">Context 组：模型这一轮看到什么 <a class="header-anchor" href="#context-组-模型这一轮看到什么" aria-label="Permalink to &quot;Context 组：模型这一轮看到什么&quot;">​</a></h1><blockquote><p><strong>在哪一组</strong>：Context 组 ｜ <strong>进入本组前</strong>：能写并验证输入/输出 schema（<a href="./../02-inference-interface/structured-output.html">structured-output</a>） ｜ <strong>本组出口</strong>：能回答「模型这一轮看到什么」的全链路——算得清预算、组得对来源、防得住腐烂 <strong>前置</strong>：<a href="./../02-inference-interface/structured-output.html">structured-output</a> ｜ <strong>下一步</strong>：<a href="./../04-grounding/embeddings-retrieval.html">嵌入与检索</a>、<a href="./../05-action/tool-calling.html">工具调用契约</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论</strong>：提示写得再好，也只能控制「怎么说」；质量与成本的另一半在「<strong>给模型看什么</strong>」。Context 组把这个问题拆成五个正交的小问题，每页管一个：怎么表达（prompt）、能装多少（context-window）、装什么（context-engineering）、跨轮历史放哪（session-memory）、仓库约定怎么声明（repo-context）。</p><p>为什么值得一个组：上下文是<strong>有限资源且边际收益递减</strong>——窗口内 token 越多，模型准确回忆越差（context rot，跨模型存在）；同时每一轮重发的内容都在计费。输入侧的策展做不好，上层（检索接地、工具执行、运营对账）都在为噪声付钱。</p><h3 id="心智模型-从意图到窗口的变换链" tabindex="-1">心智模型：从意图到窗口的变换链 <a class="header-anchor" href="#心智模型-从意图到窗口的变换链" aria-label="Permalink to &quot;心智模型：从意图到窗口的变换链&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人的意图</span></span>
<span class="line"><span>   │ ① prompt           怎么表达（任务/约束/示例/输出格式）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>可控的指令 ── ② context-window    装得下多少（token 预算、配对、输出预留）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │ ③ context-engineering 装什么（来源、优先级、压缩、防腐）</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>组装好的窗口 ── ④ session-memory  跨轮历史放哪（存储、裁剪、恢复、并发）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼ ⑤ repo-context      仓库约定怎么声明（AGENTS.md、就近优先、宿主注入）</span></span>
<span class="line"><span>模型这一轮真正看到的内容</span></span></code></pre></div><h3 id="症状路由-什么问题进哪页" tabindex="-1">症状路由：什么问题进哪页 <a class="header-anchor" href="#症状路由-什么问题进哪页" aria-label="Permalink to &quot;症状路由：什么问题进哪页&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输出不稳定、答非所问（表达问题）        → prompt</span></span>
<span class="line"><span>请求报 400 超窗、成本线性涨、输出截断    → context-window</span></span>
<span class="line"><span>塞了检索还是答不对、答案引用旧内容      → context-engineering</span></span>
<span class="line"><span>刷新丢历史、越聊越失忆、并发写坏会话    → session-memory</span></span>
<span class="line"><span>换助手就装错依赖、跑错测试命令          → repo-context</span></span></code></pre></div><h3 id="主题导航表" tabindex="-1">主题导航表 <a class="header-anchor" href="#主题导航表" aria-label="Permalink to &quot;主题导航表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>回答什么问题</th><th>出口</th><th>链接</th></tr></thead><tbody><tr><td>提示词工程</td><td>怎么把意图写成模型可执行的指令？</td><td>能写四要素提示并当代码管理</td><td><a href="./prompt.html">prompt</a></td></tr><tr><td>上下文窗口</td><td>这一轮装得下多少？</td><td>能算四块预算、识别超窗症状、保配对裁剪</td><td><a href="./context-window.html">context-window</a></td></tr><tr><td>上下文工程</td><td>这一轮该装什么？</td><td>能设计多来源组装：优先级、可见挤出、压缩防腐</td><td><a href="./context-engineering.html">context-engineering</a></td></tr><tr><td>会话与状态</td><td>跨轮历史放哪？</td><td>能建会话：预算裁剪、持久化恢复、并发防护</td><td><a href="./session-memory.html">session-memory</a></td></tr><tr><td>仓库上下文</td><td>仓库约定怎么声明？</td><td>能落一份命令真实、分层正确的 AGENTS.md</td><td><a href="./repo-context.html">repo-context</a></td></tr></tbody></table><h3 id="何时进本组-何时不进" tabindex="-1">何时进本组 / 何时不进 <a class="header-anchor" href="#何时进本组-何时不进" aria-label="Permalink to &quot;何时进本组 / 何时不进&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>写给谁</strong></td><td>把模型接进产品或工作流、开始关心质量与成本的前端 / 全栈工程师</td></tr><tr><td><strong>进</strong></td><td>提示已能写清，但多轮、外部内容（文件 / 检索 / 工具结果）、编码助手任一出现</td></tr><tr><td><strong>不进</strong></td><td>回答本身还不稳定、无法解析——先回 <a href="./../02-inference-interface/structured-output.html">structured-output</a> 把契约闭环；模型内部机制 → Learn LLM</td></tr><tr><td><strong>不是本组</strong></td><td>检索索引怎么建 → <a href="./../04-grounding/">接地组</a>；动作怎么安全执行 → <a href="./../05-action/tool-calling.html">tool-calling</a></td></tr></tbody></table><h3 id="决策表-五个主题怎么分工" tabindex="-1">决策表：五个主题怎么分工 <a class="header-anchor" href="#决策表-五个主题怎么分工" aria-label="Permalink to &quot;决策表：五个主题怎么分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>prompt</th><th>context-window</th><th>context-engineering</th><th>session-memory</th><th>repo-context</th></tr></thead><tbody><tr><td><strong>控制什么</strong></td><td>指令的表达</td><td>输入的容量</td><td>输入的内容选择</td><td>跨轮历史的存取</td><td>仓库级约定</td></tr><tr><td><strong>方向</strong></td><td>人 → 模型（意图）</td><td>系统 → 窗口（预算）</td><td>来源 → 窗口（策展）</td><td>会话 → 存储 → 窗口</td><td>仓库 → 宿主 → 窗口</td></tr><tr><td><strong>控制权</strong></td><td>文本，全在你</td><td>组装层，全在你</td><td>组装层，全在你</td><td>store 实现，全在你</td><td>仓库文件 + 宿主读取</td></tr><tr><td><strong>状态</strong></td><td>版本化文本</td><td>每轮重算</td><td>每轮重组</td><td>跨请求持久</td><td>随仓库演进</td></tr><tr><td><strong>信任域</strong></td><td>可 diff</td><td>估算 vs 精算</td><td>来源新鲜度</td><td>存储与并发</td><td>命令真实性</td></tr><tr><td><strong>最低复杂度</strong></td><td>最低，永远先试</td><td>低（单轮）到中（多轮）</td><td>中</td><td>中（+持久化）</td><td>低（一个文本文件）</td></tr></tbody></table><p>建议按 navOrder 顺序读：prompt → context-window → context-engineering → session-memory → repo-context。</p><p><strong>版本里程碑</strong>：未验证（各主题涉及的厂商能力时间线见各自主题页，本页不重复断言）。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是导航层，不设独立 fixture——本组统一的动手出口是 <a href="./context-window.html">context-window</a> 的零 key 预算分配器（15 分钟：四块配比 → 溢出告警 → 保配对裁剪，含负例）。它是整组的交汇点：提示占 system 块、历史占 history 块、检索占 retrieval 块、输出留 output 块——五个主题在一张预算表上会合。</p><p><strong>15 分钟自检</strong>（跑完 fixture 后回答）：</p><ol><li>输出预留为什么必须计入预算？（答：输入输出共享窗口；不留则 <code>stop_reason: max_tokens</code> 截断）</li><li>裁历史时哪两类消息绝对不能切断？（答：system 头；<code>tool_use</code> / <code>tool_result</code> 配对）</li><li>预算超了第一动作是什么？（答：先裁低优先级来源且挤出可见，不是静默丢、也不是换更大窗口模型）</li></ol><p>三题都答得出，本组前半程出口已达成；再跑 <a href="./context-engineering.html">context-engineering</a> 的组装器，把「来源有优先级、挤出必须可见」补齐。</p><p><strong>验收命令</strong>（即 context-window 的确定性验收）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx@4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context-window.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BUDGET-OK</span></span></code></pre></div><p><strong>清理</strong>：删除临时文件。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么「上下文」值得单独一个组" tabindex="-1">为什么「上下文」值得单独一个组 <a class="header-anchor" href="#为什么「上下文」值得单独一个组" aria-label="Permalink to &quot;为什么「上下文」值得单独一个组&quot;">​</a></h3><p>模型 API 的朴素视图是「提示进、文本出」，看起来只有 prompt 一个旋钮。工程化之后，「这一轮看到什么」至少裂成五个各有不变量的问题：token 有预算不变量、来源有优先级与失效条件、历史有存储与并发、仓库约定有就近覆盖与命令真实性。<strong>每个子问题都可以独立验收</strong>——这是把它们拆开的理由。</p><h3 id="组级不变量-各页展开-此处总纲" tabindex="-1">组级不变量（各页展开，此处总纲） <a class="header-anchor" href="#组级不变量-各页展开-此处总纲" aria-label="Permalink to &quot;组级不变量（各页展开，此处总纲）&quot;">​</a></h3><ol><li><strong>预算先算后发</strong>：任何一轮请求组装完即可判定会不会超窗（→ <a href="./context-window.html">context-window</a> I1）。</li><li><strong>裁剪不破坏结构</strong>：system 保留、tool 配对完整、挤出可见（→ I2 与 <a href="./context-engineering.html">context-engineering</a>）。</li><li><strong>每个来源有优先级与失效条件</strong>：没有优先级的组装等于先来先占（→ context-engineering）。</li><li><strong>命令必须真实</strong>：写进 AGENTS.md 的命令助手会照单执行（→ <a href="./repo-context.html">repo-context</a>）。</li></ol><h3 id="两条通用的「到此为止」" tabindex="-1">两条通用的「到此为止」 <a class="header-anchor" href="#两条通用的「到此为止」" aria-label="Permalink to &quot;两条通用的「到此为止」&quot;">​</a></h3><ul><li>注意力数学、KV cache、记忆实现四模式 → Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">第 15 章</a>（本组只取其工程含义）。</li><li>厂商窗口数字、缓存价格、token 计数接口字段 → 各家官方文档当天页面（本组不维护数字清单）。</li></ul><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><h3 id="组级验收清单-exit-criteria" tabindex="-1">组级验收清单（Exit criteria） <a class="header-anchor" href="#组级验收清单-exit-criteria" aria-label="Permalink to &quot;组级验收清单（Exit criteria）&quot;">​</a></h3><ul><li>[ ] 能把一条模糊需求改写成四要素提示，并让提示进版本库（prompt）</li><li>[ ] 能为一轮请求算四块 token 预算，裁剪不切断 tool 配对（context-window）</li><li>[ ] 能给多来源定优先级，挤出有报告，稳定来源在前缀（context-engineering）</li><li>[ ] 能给多轮对话建会话：预算裁剪、持久化恢复、并发防护（session-memory）</li><li>[ ] 能给自己的仓库落一份命令真实、分层正确的 AGENTS.md（repo-context）</li></ul><h3 id="调试-runbook-组级症状" tabindex="-1">调试 runbook（组级症状） <a class="header-anchor" href="#调试-runbook-组级症状" aria-label="Permalink to &quot;调试 runbook（组级症状）&quot;">​</a></h3><h4 id="r1-「症状路由错了层-改提示不裁窗」" tabindex="-1">R1 「症状路由错了层，改提示不裁窗」 <a class="header-anchor" href="#r1-「症状路由错了层-改提示不裁窗」" aria-label="Permalink to &quot;R1 「症状路由错了层，改提示不裁窗」&quot;">​</a></h4><p><strong>症状</strong>：多轮会话质量下降，团队连续改了三版提示词没有改善。 <strong>证据</strong>：逐轮 token 计数曲线仍单调上涨——问题不在表达，在预算。 <strong>处理</strong>：按症状路由表回 <a href="./context-window.html">context-window</a> R1；表达类症状（不稳定、答非所问）才进 <a href="./prompt.html">prompt</a>。 <strong>完成标准</strong>：失败样本先归因（表达 / 预算 / 内容 / 历史 / 约定）再动手，归因记录进 PR。</p><h4 id="r2-「越聊越笨」的定位链" tabindex="-1">R2 「越聊越笨」的定位链 <a class="header-anchor" href="#r2-「越聊越笨」的定位链" aria-label="Permalink to &quot;R2 「越聊越笨」的定位链&quot;">​</a></h4><p><strong>症状</strong>：长会话后半段回答质量明显下滑。 <strong>证据</strong>：依次检查——token 曲线是否逼近窗口（预算）→ 检索片段是否陈旧（内容）→ 关键轮次是否被裁（历史）。 <strong>处理</strong>：预算满 → 裁剪或压缩；内容旧 → 换 JIT；历史丢 → 调整保留策略（分别见 <a href="./context-window.html">context-window</a>、<a href="./context-engineering.html">context-engineering</a>、<a href="./session-memory.html">session-memory</a>）。 <strong>完成标准</strong>：同类会话不再随轮次单调劣化；定位链写进团队排障文档。</p><h4 id="r3-「换助手行为就不一致」" tabindex="-1">R3 「换助手行为就不一致」 <a class="header-anchor" href="#r3-「换助手行为就不一致」" aria-label="Permalink to &quot;R3 「换助手行为就不一致」&quot;">​</a></h4><p><strong>症状</strong>：Cursor 里对的，Claude Code 里装错依赖；新人开局总要踩一遍坑。 <strong>证据</strong>：仓库根没有 AGENTS.md，或命令与实际不符。 <strong>处理</strong>：按 <a href="./repo-context.html">repo-context</a> R1 落文件；monorepo 子包例外用嵌套文件。 <strong>完成标准</strong>：新会话首轮用对命令；跨工具、跨成员行为一致。</p><h3 id="反模式清单-组级" tabindex="-1">反模式清单（组级） <a class="header-anchor" href="#反模式清单-组级" aria-label="Permalink to &quot;反模式清单（组级）&quot;">​</a></h3><ul><li>跳过预算直接堆检索：内容越塞越多，质量反而下降——rot 不因窗口变大而消失。</li><li>用更长提示修内容问题：该裁的裁、该换来源的换来源。</li><li>组装逻辑散落多处：绕过优先级与守卫的拼装是第二套真相。</li><li>失败静默吞掉：挤出、裁剪、过期都必须有报告，否则不可调试。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="四级阅读路线" tabindex="-1">四级阅读路线 <a class="header-anchor" href="#四级阅读路线" aria-label="Permalink to &quot;四级阅读路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级</th><th>读什么</th><th>为什么是这个顺序</th></tr></thead><tbody><tr><td>Beginner</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview" target="_blank" rel="noreferrer">Anthropic 提示工程总览</a> ｜ <a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">OpenAI 指南 context window 节</a></td><td>先有「表达」与「预算」的直觉</td></tr><tr><td>Builder</td><td>本组五页按序读完 + <a href="./context-window.html">context-window fixture</a> 跑通</td><td>手上有一套可回归的预算与组装循环</td></tr><tr><td>Operator</td><td>两家 prompt caching 与 token counting 文档 ｜ <a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a></td><td>上线后的对账、命中率与团队约定</td></tr><tr><td>Researcher</td><td><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic：Effective context engineering</a> ｜ <a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">Chroma：Context Rot</a> ｜ Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">第 15 章</a></td><td>心智模型、衰减实证与机制层</td></tr></tbody></table><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>本组五主题页</td><td>L1</td><td><a href="./prompt.html">prompt</a> · <a href="./context-window.html">context-window</a> · <a href="./context-engineering.html">context-engineering</a> · <a href="./session-memory.html">session-memory</a> · <a href="./repo-context.html">repo-context</a></td><td>主路径</td><td>—</td><td>按序读</td></tr><tr><td>Anthropic context engineering</td><td>L1</td><td><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents</a></td><td>心智模型总纲</td><td>元原则 / JIT / compaction / rot</td><td>读原文</td></tr><tr><td>OpenAI prompt engineering</td><td>L1</td><td><a href="https://developers.openai.com/api/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/prompt-engineering</a></td><td>官方预算视角</td><td>窗口以 token 计</td><td>读其 Structured Outputs</td></tr><tr><td>Anthropic Context windows</td><td>L1</td><td><a href="https://platform.claude.com/docs/en/build-with-claude/context-windows" target="_blank" rel="noreferrer">https://platform.claude.com/docs/en/build-with-claude/context-windows</a></td><td>窗口与计费口径</td><td>输入输出共享预算</td><td>配 token counting 用</td></tr><tr><td>agents.md</td><td>L1</td><td><a href="https://agents.md/" target="_blank" rel="noreferrer">https://agents.md/</a></td><td>仓库级上下文约定</td><td>格式、就近优先、工具支持面</td><td>给仓库落一份</td></tr><tr><td>Chroma Context Rot</td><td>L4</td><td><a href="https://research.trychroma.com/context-rot" target="_blank" rel="noreferrer">https://research.trychroma.com/context-rot</a></td><td>衰减实证</td><td>长 ctx 检索退化</td><td>设计长文任务前读</td></tr><tr><td>Learn LLM 第 15 章</td><td>L2</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/15-prompt-memory</a></td><td>机制层桥接</td><td>注意力 / KV cache / 记忆四模式</td><td>要「为什么」时读</td></tr></tbody></table><p>（retrievedAt: 2026-09-01。）</p><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>本组结论建立在 2026-09-01 检索的两家官方文档与 Anthropic 工程文章上；厂商窗口数字、缓存价格持续漂移，复核周期建议 ≤ 6 个月。</li><li>五主题切分是本仓的教学组织，服务于各自可验收的出口，不是行业标准分类。</li><li>未决：context rot 的量化临界点无通用公式（→ <a href="./context-window.html">context-window</a>）；compaction 保留策略无公开基准（→ <a href="./context-engineering.html">context-engineering</a>）。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>输入侧闭环后，检索依据怎么建 → <a href="./../04-grounding/embeddings-retrieval.html">嵌入与检索</a>、<a href="./../04-grounding/rag.html">RAG</a>。</li><li>要执行动作 → <a href="./../05-action/tool-calling.html">工具调用契约</a>。</li><li>预算与成本进运营口径 → <a href="./../08-production/cost-performance.html">成本与性能</a>。</li><li>注意力与记忆机制 → Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">第 15 章</a>。</li></ul>`,55)])])}const f=e(o,[["render",d]]);export{x as __pageData,f as default};
